/// Finds the maximum value in `v[0..=end]` and returns a tuple of
/// (max_value, index_of_max).
///
/// # Panics
///
/// Panics if `v` is empty or if `end` is out of bounds.
#[verifier::trusted]
#[verifier::requires(v.len() > 0)]
#[verifier::requires(end < v.len())]
#[verifier::ensures(|res: (i32, usize)| {
    let (max_val, max_idx) = res;
    // The returned index is in range 0..=end
    max_idx <= end
    // max_val really is the element at that index
    && max_val == v[max_idx]
    // and it is indeed at least as large as every element in the prefix
    && forall(|j: usize| j <= end ==>
         v[j] <= max_val
    )
})]
pub fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "Input slice must not be empty");
    assert!(end < v.len(),  "end index out of bounds");

    let mut max_val = v[0];
    let mut max_idx = 0;
    for idx in 1..=end {
        if v[idx] > max_val {
            max_val = v[idx];
            max_idx = idx;
        }
    }
    (max_val, max_idx)
}

/// Finds the minimum value in `v[start..]` and returns a tuple of
/// (min_value, index_of_min).
///
/// # Panics
///
/// Panics if `v` is empty or if `start` is out of bounds.
#[verifier::trusted]
#[verifier::requires(v.len() > 0)]
#[verifier::requires(start < v.len())]
#[verifier::ensures(|res: (i32, usize)| {
    let (min_val, min_idx) = res;
    // the returned index is in the suffix
    start <= min_idx && min_idx < v.len()
    // min_val really is the element at that index
    && min_val == v[min_idx]
    // and it is indeed at most every element in the suffix
    && forall(|j: usize| start <= j && j < v.len() ==>
         v[j] >= min_val
    )
})]
pub fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "Input slice must not be empty");
    assert!(start < v.len(),  "start index out of bounds");

    let mut min_val = v[start];
    let mut min_idx = start;
    for idx in (start + 1)..v.len() {
        if v[idx] < min_val {
            min_val = v[idx];
            min_idx = idx;
        }
    }
    (min_val, min_idx)
}

/// Determines whether `p` is a strict partition barrier in `v`.
///
/// Returns `true` if every element at indices `<= p` is strictly less
/// than every element at indices `> p`.  If `p` is the last index,
/// returns `true` (vacuously).
///
/// # Panics
///
/// Panics if `v` is empty or if `p` is out of bounds.
#[verifier::trusted]
#[verifier::requires(v.len() > 0)]
#[verifier::requires(p < v.len())]
#[verifier::ensures(|res: bool| {
    // For all i ≤ p and j > p (still inside the slice), v[i] < v[j].
    // If p = v.len()-1 then there is no j > p < v.len(), so the
    // quantifier is vacuously true, and we get res == true, as desired.
    res == forall(|i: usize, j: usize| 
        i <= p && j > p && j < v.len() ==>
        v[i] < v[j]
    )
})]
pub fn barrier(v: &[i32], p: usize) -> bool {
    assert!(!v.is_empty(), "Input slice must not be empty");
    assert!(p < v.len(),  "Partition index out of bounds");

    // If p is the last index, there is no suffix to compare, so it's true.
    if p + 1 >= v.len() {
        return true;
    }

    let (prefix_max, _max_idx) = find_max_in_prefix(v, p);
    let (suffix_min, _min_idx) = find_min_in_suffix(v, p + 1);

    prefix_max < suffix_min
}

